  "ui.wpAdminAgentFrameApp.feedback100": "Nincs elérhető helyi CLI-futtató. Nyissa meg a Beállítások → Végrehajtás részt, és csatlakoztasson OpenCode-ot vagy más támogatott futtatót.",
