  "ui.wpAdminAgentFrameApp.feedback102": "Csatolja újra ezt: {value1}, hogy megtalálható legyen a feltöltési munkaterülete.",
  "ui.wpAdminAgentFrameApp.feedback103": "A kiválasztott olvasási célhoz ({value1}) a jelenlegi WordPress-adminisztrációs környezet nem ad jogosultságot. Nem módosítottam semmit.",
  "ui.wpAdminAgentFrameApp.feedback104": "Nem sikerült frissen engedélyezni a kifejezetten kiválasztott WordPress-bejegyzést ({value1}). Nem módosítottam semmit.",
  "ui.wpAdminAgentFrameApp.feedback105": "Nem sikerült teljesen betölteni az aktuális Gutenberg-dokumentumot ({value1}). Nem módosítottam semmit.",
  "ui.wpAdminAgentFrameApp.feedback106": "Az aktuális Gutenberg-dokumentum csak kötött, darabolt pillanatképként érhető el. A teljes dokumentum szerkesztése nem készíthető elő az összes szükséges darab beolvasása előtt. Nem módosítottam semmit.",
  "ui.wpAdminAgentFrameApp.feedback107": "Az aktuális Gutenberg-bejegyzésben nem mentett szerkesztői módosítások vannak. Mentse vagy frissítse, mielőtt a Pixflow beolvassa vagy tartalomfüggő szerkesztést készít elő. Nem módosítottam semmit.",
  "ui.wpAdminAgentFrameApp.feedback108": "Az összes Gutenberg-blokk törlése jelenleg nem támogatott. A Pixflow nem értelmezte a kérést üres tartalommal való cserének, és semmi sem változott.",
  "ui.wpAdminAgentFrameApp.feedback109": "A Pixflow nem tudta megállapítani, hogy az üzenet a függőben lévő pontosításra válaszol-e, vagy új kérést indít. Nem készült ellenőrzés, és semmi sem változott.",
  "ui.wpAdminAgentFrameApp.feedback110": "Az aktuális Gutenberg-dokumentum darabolt, és nincs teljesen beolvasva, ezért a Pixflow nem készíthet teljes dokumentumellenőrzést. Nem módosítottam semmit.",
  "ui.wpAdminAgentFrameApp.feedback111": "Nem érkezett kifejezett kérés a teljes Gutenberg-tartalom cseréjére, ezért a Pixflow nem cserélte le az aktuális dokumentumot. Semmi sem változott.",
  "ui.wpAdminAgentFrameApp.feedback112": "A Pixflow nem tudta frissíteni a WordPress-objektum jogosultságát az előző művelet után. A korábbi műveletek vissza lesznek vonva.",
  "ui.wpAdminAgentFrameApp.feedback113": "Az előfeltételként szükséges bejegyzés nem jött létre érvényes WordPress-azonosítóval. A korábbi műveletek vissza lesznek vonva.",
  "ui.wpAdminAgentFrameApp.feedback114": "A Pixflow nem tudott friss jogosultságot igazolni az új bejegyzéshez. A korábbi műveletek vissza lesznek vonva.",
  "ui.wpAdminAgentFrameApp.feedback115": "Az új bejegyzés nem szerkeszthető cél a blokkszerkesztőben. A korábbi műveletek vissza lesznek vonva.",
