  "wp.message.26a6374fbf59": "Egy Pixflow-bővítmény nem indult el. Ellenőrizze a Pixflow-bővítmények kompatibilitását, majd töltse újra az oldalt. Más funkciók továbbra is elérhetők lehetnek.",
  "wp.message.ca7714cffbcc": "Pro aktiválása",
  "wp.message.197c83a2f752": "Hozza vissza prémium eszközeit a Pro-bővítménnyel. Licence, tartalmai és mentett beállításai megmaradnak. Ha használta a Bricks kétlépcsős hitelesítését, a Pro aktiválása után kapcsolja be újra a beállításokban.",
  "wp.message.2ffdcbc380ea": "Alkosson kedvenc oldalkészítőjében. Egészítse ki munkafolyamatát megjegyzésekkel, hanggal, dizájnrendszerekkel és képgenerálással.",
  "wp.message.40ed1102964b": "Pro-próbaidőszak ellenőrzése",
  "wp.message.e9cccd3ef5fc": "Az elutasítás mentése nem sikerült. Próbálja újra.",
  "wp.message.1372089fb797": "Pixflow Pro-szalag bezárása",
  "wp.message.5e3ba715018d": "Pro letöltése",
  "wp.message.fb2e6d87b44c": "Több lehetőség a Pixflow Design Pro segítségével",
  "wp.message.9934717ca744": "Frissítse az oldalt, és próbálja újra.",
  "wp.message.7c78f9990490": "A Pro 7 napos próbaverziójának indítása",
  "wp.message.f89b4dcf2c2e": "Próbálja ki a Pro verziót 7 napig",
  "wp.message.69ecce9deb2d": "Ezt az értesítést nem zárhatja be.",
  "wp.message.927384e7eed8": "Pixflow-csomagja tartalmazza a Pro verziót",
  "wp.message.64585a3a39ef": "[%s] A kétlépcsős hitelesítés alaphelyzetbe állítva",
  "wp.message.97c3ac935cc2": "[%s] Az Ön ellenőrzőkódja",
  "wp.message.b075b6e113fc": "10 perc",
  "wp.message.8bbe8944007a": "Kétlépcsős hitelesítés",
  "wp.message.c2bf03beb4f6": "Kétlépcsős hitelesítés beállítása",
  "wp.message.3170543ce47c": "5 perc",
  "wp.message.0d1fa0dfcc9e": "6 számjegyű kód",
  "wp.message.8b6693be283d": "Fiókpanel",
  "wp.message.107a3671eb84": "Aktív/befejezett állapot színe",
  "wp.message.47d932f4c02a": "Aktív/befejezett lépés számának színe",
  "wp.message.73dbcf028ec6": "Fiókja védelméhez adjon hozzá egy második ellenőrzési módot.",
  "wp.message.529da8588051": "A bejelentkezés befejezéséhez további ellenőrzés szükséges.",
  "wp.message.6b49000156c3": "A rendszergazdák akkor használhatják ezt a vészhelyzeti visszaállítást, ha a felhasználó minden hitelesítési eszközét és helyreállítási kódját elveszítette.",
  "wp.message.4ea44caf5d6e": "Űrlap után",
  "wp.message.1be05927766c": "Egy rendszergazda eltávolította a kétlépcsős hitelesítést a fiókjából. Ha nem számított erre a változásra, állítsa vissza jelszavát, és azonnal lépjen kapcsolatba a webhely rendszergazdájával.",
  "wp.message.bd4a7c92a53f": "Hitelesítési/e-mail-/hozzáférésikulcs-ablak",
  "wp.message.09a12ace273f": "Hitelesítő alkalmazás",
  "wp.message.a4c801f3d189": "A hitelesítő alkalmazás készen áll",
  "wp.message.9fd5a3f4f23e": "A hitelesítő alkalmazás beállítása ezen a webhelyen le van tiltva.",
