  "wp.message.1d3f35031a5a": "Pixflow egyéni Splide-kód",
  "wp.message.b73a688afd1a": "A Pixflow Design Pro a Pixflow Design alapbővítmény kompatibilis verzióját igényli. Frissítse mindkét bővítményt együtt.",
  "wp.message.7ecf123f8f20": "A Pixflow Design Pro használatához a Pixflow Design alapbővítménynek aktívnak kell lennie.",
  "wp.message.46d86360f524": "Pixflow kétlépcsős hitelesítés",
  "wp.message.e70f8f3b8315": "Helyezze el ezt az elemet egyszer egy webhelyszintű Bricks-láblécsablonban. A hozzájárulási szolgáltatások, az észlelés és a blokkolás itt állítható be: Pixflow Design → Bricks-bővítmények → Hozzájárulás a sütikhez.",
