  "wp.message.aadd9cf83b66": "A kiszolgáló nem tudja biztonságosan titkosítani a hitelesítő titkos kulcsát. Forduljon a webhely rendszergazdájához.",
  "wp.message.e244f187f696": "Ön",
  "wp.message.06b2bc8020aa": "Ez eltávolítja a fiók összes kétlépcsős hitelesítési módját, hozzáférési kulcsát és helyreállítási kódját. Folytatja?",
