  "ui.finalOnboarding.e76c3bfd0e": "Csatlakozz közvetlenül a szolgáltatódhoz. Az API-használat külön kerül számlázásra.",
  "ui.finalOnboarding.1be451ef72": "Folytatás AI nélkül",
  "ui.finalOnboarding.88e6e83b86": "Használd a WordPress-munkaterületet. Később hozzáadhatsz AI-t, ha szeretnél.",
  "ui.finalOnboarding.105e56e56f": "Miért válaszd a helyi CLI-t?",
  "ui.finalOnboarding.5df057fcd7": "Az API-használat külön kerül számlázásra",
  "ui.finalOnboarding.44e30ed15f": "A BYOK használatához API-kulcs kell. Az AI-szolgáltató az API-használatot a CLI-előfizetéstől külön számlázza, ezért ez többletköltséget jelenthet a CLI-fiókhoz tartozó vagy heti keret felhasználása helyett.",
